#!/usr/bin/env bash
# Restore the icon theme that was active before this template was enabled.
# Does nothing when there is nothing recorded to restore.
# This section has been AI-generated by DeepSeek V4.1 Flash Free on 25.11.2026
# (rewritten from the Gemini 3.8 Flash version of the same hook).
set -euo pipefail

CONFIG_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
STATE="$CONFIG_HOME/noctalia/slot-beauty-icons.state"
DEST="$DATA_HOME/icons/Slot-Beauty-Dark-Icons-V-2-Noctalia"

# shellcheck source=ini.sh
source "$CONFIG_DIR/ini.sh"

[[ -f "$STATE" ]] || exit 0

declare -A remembered=()
while IFS='=' read -r key value; do
  [[ -n "$key" && ! "$key" =~ ^# ]] || continue
  remembered["$key"]="$value"
done < "$STATE"

# A restore that fails must not cost the user their recorded state: retrying is
# only possible while the state file survives, so count failures and decide at
# the very end whether it is safe to delete.
failures=0
fail() {
  echo "Warning: $*" >&2
  failures=$((failures + 1))
}

# drop_created <file>
# Undo a settings file that apply.sh created from scratch.  Our key is removed
# first; if nothing else is left the file (and its now-empty directory) goes
# away.  A file the user has since added settings to is kept untouched.
drop_created() {
  local file="$1"
  ini_unset "$file" Settings gtk-icon-theme-name || return 1
  if [[ -f "$file" ]] \
     && grep -qvE '^[[:space:]]*(\[[^]]*\])?[[:space:]]*$' "$file"; then
    return 0
  fi
  rm -f -- "$file"
  rmdir -- "$(dirname -- "$file")" 2>/dev/null || true
}

# 1. GSettings
if [[ -v remembered[gsettings] ]]; then
  value="${remembered[gsettings]}"
  if command -v gsettings >/dev/null 2>&1; then
    if [[ "$value" == "__UNSET__" || "$value" == "__RESET__" ]]; then
      gsettings reset org.gnome.desktop.interface icon-theme 2>/dev/null \
        || fail "could not reset the GSettings icon theme"
    elif [[ -n "$value" ]]; then
      if ! gsettings set org.gnome.desktop.interface icon-theme "'${value//\'/}'" 2>/dev/null; then
        fail "could not restore the GSettings icon theme to '$value'"
      fi
    fi
  fi
fi

# 2. GTK3
GTK3="$CONFIG_HOME/gtk-3.0/settings.ini"
if [[ "${remembered[gtk3_created]:-}" == "1" ]]; then
  drop_created "$GTK3" || fail "could not clean up $GTK3"
elif [[ -v remembered[gtk3] ]]; then
  value="${remembered[gtk3]}"
  if [[ "$value" == "__UNSET__" ]]; then
    ini_unset "$GTK3" Settings gtk-icon-theme-name || fail "could not clear the icon theme in $GTK3"
  else
    ini_set "$GTK3" Settings gtk-icon-theme-name "$value" || fail "could not restore $GTK3"
  fi
fi

# 3. GTK4
GTK4="$CONFIG_HOME/gtk-4.0/settings.ini"
if [[ "${remembered[gtk4_created]:-}" == "1" ]]; then
  drop_created "$GTK4" || fail "could not clean up $GTK4"
elif [[ -v remembered[gtk4] ]]; then
  value="${remembered[gtk4]}"
  if [[ "$value" == "__UNSET__" ]]; then
    ini_unset "$GTK4" Settings gtk-icon-theme-name || fail "could not clear the icon theme in $GTK4"
  else
    ini_set "$GTK4" Settings gtk-icon-theme-name "$value" || fail "could not restore $GTK4"
  fi
fi

# 4. Qt5ct
QT5="$CONFIG_HOME/qt5ct/qt5ct.conf"
if [[ -v remembered[qt5] && -f "$QT5" ]]; then
  value="${remembered[qt5]}"
  if [[ "$value" == "__UNSET__" ]]; then
    ini_unset "$QT5" Appearance icon_theme || fail "could not clear the icon theme in $QT5"
  else
    ini_set "$QT5" Appearance icon_theme "$value" || fail "could not restore $QT5"
  fi
fi

# 5. Qt6ct
QT6="$CONFIG_HOME/qt6ct/qt6ct.conf"
if [[ -v remembered[qt6] && -f "$QT6" ]]; then
  value="${remembered[qt6]}"
  if [[ "$value" == "__UNSET__" ]]; then
    ini_unset "$QT6" Appearance icon_theme || fail "could not clear the icon theme in $QT6"
  else
    ini_set "$QT6" Appearance icon_theme "$value" || fail "could not restore $QT6"
  fi
fi

if (( failures == 0 )); then
  rm -f -- "$STATE"
else
  echo "Warning: $failures restore step(s) failed; keeping $STATE so undo can be retried." >&2
fi

# Notify file watchers.  Undo never removes the derived theme, but guard the
# touches so a missing directory cannot turn a good restore into an error.
[[ -d "$DEST" ]] && touch "$DEST" 2>/dev/null || true
[[ -d "$DATA_HOME/icons" ]] && touch "$DATA_HOME/icons" 2>/dev/null || true

(( failures == 0 )) || exit 1
exit 0
# End of AI-generated section.
